  "decisions": [
    {
      "selected_poi_ids": [
        "bj004",
        "bj001",
        "bj002"
      ],
      "selection_reasoning": "首选中国国家博物馆（bj004）与故宫博物院（bj001）为历史文化类且主要以室内或混合参观为主，文化价值高且在雨天或高温时相对更适宜；天坛公园（bj002）作为户外古建筑群步行量中等，可选择性参观祭坛主区以减少步行。推荐集合为3处，兼顾室内参观与经典历史场所，便于老人家以较少步行获取丰富文化体验。",
      "rejected_poi_ids": [
        "bj003",
        "bj005"
      ],
      "rejection_reasoning": "颐和园（bj003）与南锣鼓巷（bj005）虽具文化价值，但两者整体需要较多步行（walking_level: high / medium 且颐和园推荐时长长），不符合“少走路”优先需求，因此未列为首选。"
    }
  ],
  "risks": [
    {
      "risk_type": "walking_burden",
      "description": "故宫博物院虽然为室内/混合，但自身园区大、推荐参观时长较长（约4小时），老人可能感到疲劳。建议缩短参观深度或在内部使用休息点来降低负担.",
      "mitigation": "优先安排中国国家博物馆（室内、步行中等）与在故宫仅参观主要展区；携带便携座椅或利用馆内座位休息；分段参观。"
    },
    {
      "risk_type": "outdoor_weather_impact",
      "description": "天坛为露天古建筑公园，户外比重大（outdoor_ratio 0.9），在极端天气（雨、炎热）时对老人体验不利。",
      "mitigation": "在天气不佳时优先选择室内场所（中国国家博物馆）；如仍前往，可选择早晨或傍晚较凉时段，准备遮阳/雨具并沿主轴线精简路线。"
    },
    {
      "risk_type": "visit_duration",
      "description": "部分景点推荐时长较长（故宫4h、颐和园4h、中国国家博物馆3.5h），持续时间长可能导致体力不足。",
      "mitigation": "压缩每处景点的停留时间至2小时左右或分次参观，安排休息、就近餐饮与坐车接驳。"
    }
  ],
  "confidence": 0.86
}

